export const relaySupportsBan = (v) => { const m = /^world(\d+)$/.exec(typeof v === 'string' ? v : ''); return !!m && Number(m[1]) >= BAN_RELAY_MIN; };
/** CHAT-LANG: the relay that opens the language channels (CHAT_LANGS in its CHAT_ROOMS) - an older one refuses the key
 *  ('no such room'), so the Language tab joins only once the World link's welcome names this one or later. */
export const LANG_RELAY_MIN = 196;
export const relaySupportsLang = (v) => { const m = /^world(\d+)$/.exec(typeof v === 'string' ? v : ''); return !!m && Number(m[1]) >= LANG_RELAY_MIN; };
/** CHAT-TRADE: the relay that opens the Trade and LFG channels (both in its CHAT_ROOMS) - an older one refuses the key
 *  ('no such room'), so neither tab joins until the World link's welcome names this one or later. */
export const TRADE_CHAN_RELAY_MIN = 201;
export const relaySupportsTradeChan = (v) => { const m = /^world(\d+)$/.exec(typeof v === 'string' ? v : ''); return !!m && Number(m[1]) >= TRADE_CHAN_RELAY_MIN; };
export const duelGate = (bucket, nowMs) => tokenGate(bucket, nowMs, DUEL_HZ_MAX);
export const duelInGate = (bucket, nowMs) => tokenGate(bucket, nowMs, DUEL_IN_HZ_MAX);
const intIn = (v, lo, hi) => Number.isInteger(v) && v >= lo && v <= hi;
/** A world-frame point, as the pose carries one: natives on x and z inside the world, metres on y. */
function duelPoint(p) {
  if (!Array.isArray(p) || p.length !== 3 || !p.every(finite)) return null;
  if (Math.abs(p[0]) > POSE_BOUND || Math.abs(p[2]) > POSE_BOUND || Math.abs(p[1]) > POSE_Y_BOUND) return null;   // TV-BEYOND: either way
  return [p[0], p[1], p[2]];
}
/** The weapon a blow was struck with: `t` template, `m` material, `c` condition as a percentage of its maximum. */
function duelWeapon(w) {
  if (!w || typeof w !== 'object' || Array.isArray(w)) return null;
  if (!intIn(w.t, 0, DUEL_TEMPLATE_MAX) || !intIn(w.m, 0, DUEL_MATERIAL_MAX) || !intIn(w.c, 0, 100)) return null;
  return { t: w.t, m: w.m, c: w.c };
}
/**
 * One duel frame's data, PROJECTED: `{to, k, s, ...exactly what its kind carries}` or null - anything outside refuses
 * the whole frame (half a blow is nobody's to guess). One home: the relay's parser, the sender's sendDuel and the
 * receiver's arm run this same function.
 */
export function validDuelData(d) {
  if (!d || typeof d !== 'object' || Array.isArray(d)) return null;
  if (typeof d.k !== 'string' || !DUEL_KINDS.includes(d.k)) return null;
  const to = typeof d.to === 'string' && ID_RE.test(d.to) ? d.to : null;
  const s = typeof d.s === 'string' && DUEL_SID_RE.test(d.s) ? d.s : null;
  if (!to || !s) return null;
  const out = { to, k: d.k, s };
  switch (d.k) {
    case 'ask': case 'yes': case 'no': break;
    case 'start': {
      const c = duelPoint(d.c);
      if (!c) return null;
      out.c = c; break;
    }
    case 'cancel': case 'end': {
      if (d.why === undefined) { if (d.k === 'end') return null; break; }
      if (typeof d.why !== 'string' || !DUEL_WHY.includes(d.why)) return null;
      out.why = d.why; break;
    }
    case 'strike': {
      // INT8: the damage the striker rolled, for the referee to clip - never a sheet for the defender to resolve
      const p = duelPoint(d.p);
      if (!intIn(d.n, 1, DUEL_SEQ_MAX) || !DUEL_BLOWS.includes(d.by) || !p || !intIn(d.d, 0, DUEL_DMG_MAX)) return null;
      out.n = d.n; out.by = d.by; out.p = p; out.d = d.d;
      if (d.w !== undefined && d.w !== null) { const w = duelWeapon(d.w); if (!w) return null; out.w = w; }
      if (d.sw !== undefined) { if (!DUEL_SWINGS.includes(d.sw)) return null; out.sw = d.sw; }
      if (d.at !== undefined) { if (!intIn(d.at, 0, DUEL_DRAW_MS_MAX)) return null; out.at = d.at; }
      break;
    }
    case 'spell': {
      // INT8: the harm the caster's own game counted (combat/siegeCombat.js siegeSpellNumbers), for the referee
      const p = duelPoint(d.p);
      if (!intIn(d.n, 1, DUEL_SEQ_MAX) || !p || !intIn(d.d, 0, DUEL_DMG_MAX)) return null;
      out.n = d.n; out.p = p; out.d = d.d; break;
    }
    default: return null;
  }
  if (JSON.stringify(out).length > DUEL_DATA_MAX) return null;
  return out;
}

/** INT8: the relay that first REFEREES a duel (net/duel/duelRef.js) - a client meeting an older one duels nobody: its blows
 *  would be routed for a defender that no longer resolves them. */
export const DUEL_REF_RELAY_MIN = 185;   // world183, then world184, on its branch, renumbered past CHAP4c's world183 and PERF-RELAY1's world184 at the merges
export const relaySupportsDuelRef = (v) => { const m = /^world(\d+)$/.exec(typeof v === 'string' ? v : ''); return !!m && Number(m[1]) >= DUEL_REF_RELAY_MIN; };
/** INT11: the relay that first COUNTS a boss fight's bodies (net/bossBody.js) - a client meeting an older one says no
 *  `vt` (an older relay's gate, `sd` and `serpent` words know no such kind, and its socket would be struck for junk). */
export const BOSS_REF_RELAY_MIN = 188;   // world186 on its branch, renumbered past SD-HERALD's world186 and WAGONS1's world187 at the merge
export const relaySupportsBossRef = (v) => { const m = /^world(\d+)$/.exec(typeof v === 'string' ? v : ''); return !!m && Number(m[1]) >= BOSS_REF_RELAY_MIN; };
/** INT8: the referee's word kinds (`{t:'dref', k, s, ...}`, the relay's alone - it routes none a client sends). */
export const DUEL_REF_KINDS = Object.freeze(['bout', 'hp', 'end', 'no']);
/** INT8: the longest receipt the referees hand over - a duel's (net/duel/duelReceipt.js DUEL_RECEIPT_MAX) or, SEA-BOUNTY,
 *  a fall's (net/wild/wildReceipt.js WILD_RECEIPT_MAX - its room and its killer's character signed too): the longer, pinned. */
export const DUEL_REF_RECEIPT_MAX = 512;
/** INT8: the two fighters' vitality as the referee says it - `[[id, hp, max], [id, hp, max]]`, the challenger first. */
function duelRefVitals(h) {
  if (!Array.isArray(h) || h.length !== 2) return null;
  const out = [];
  for (const v of h) {
    if (!Array.isArray(v) || v.length !== 3 || typeof v[0] !== 'string' || !ID_RE.test(v[0]) || !intIn(v[1], 0, CARD_VITAL_MAX) || !intIn(v[2], 1, CARD_VITAL_MAX)) return null;
    out.push([v[0], Math.min(v[1], v[2]), v[2]]);
  }
  return out[0][0] === out[1][0] ? null : out;
}
/**
 * INT8: THE REFEREE'S WORD ON A DUEL, PROJECTED - the relay's `{t:'dref', ...}` to a fighter, or null:
 *   bout  { s, op, ms, h }       the bout is set: `op` my opponent's id, `ms` the countdown left, both whole
 *   hp    { s, by, to, d, r, h } a blow or a cast landed: who on whom, what it dealt, its kind (SIEGE_HIT's), both left
 *   end   { s, w, why, rc? }     the bout is over: `w` the winner's id ('' - none), its DUEL_WHY word, and when it named a
 *                                winner the relay's signed receipt (net/duel/duelReceipt.js `d1`) for the account service
 *   no    { s, why }             a start the relay would set no bout on (its DUEL_WHY word): the duel is off
 */
export function validDuelRefOut(m) {
  if (!m || typeof m !== 'object' || m.t !== 'dref' || typeof m.k !== 'string' || !DUEL_REF_KINDS.includes(m.k)) return null;
  const s = typeof m.s === 'string' && DUEL_SID_RE.test(m.s) ? m.s : null;
  if (!s) return null;
  switch (m.k) {
    case 'bout': {
      const h = duelRefVitals(m.h);
      if (typeof m.op !== 'string' || !ID_RE.test(m.op) || !intIn(m.ms, 0, 60_000) || !h) return null;
      return { k: 'bout', s, op: m.op, ms: m.ms, h };
    }
    case 'hp': {
      const h = duelRefVitals(m.h);
      if (typeof m.by !== 'string' || !ID_RE.test(m.by) || typeof m.to !== 'string' || !ID_RE.test(m.to) || !intIn(m.d, 0, CARD_VITAL_MAX) || !intIn(m.r, 0, 2) || !h) return null;
      return { k: 'hp', s, by: m.by, to: m.to, d: m.d, r: m.r, h };
    }
    case 'end': {
      if (typeof m.w !== 'string' || (m.w !== '' && !ID_RE.test(m.w)) || typeof m.why !== 'string' || !DUEL_WHY.includes(m.why)) return null;
      if (m.rc !== undefined && (typeof m.rc !== 'string' || !m.rc.length || m.rc.length > DUEL_REF_RECEIPT_MAX)) return null;
      return { k: 'end', s, w: m.w, why: m.why, ...(m.rc !== undefined ? { rc: m.rc } : {}) };
    }
    case 'no': {
      if (typeof m.why !== 'string' || !DUEL_WHY.includes(m.why)) return null;
      return { k: 'no', s, why: m.why };
    }
    default: return null;
  }
}

// ═══ LEGACY7 part three: TWO PLAYERS WED ═══════════════════════════════════════════════════════════════════════════
//
// (2026-10-06, Mac: "online integration with permadeath (Bloodline) or non-permadeath (Enduring)" - the design's "two
// players' characters may wed: both in the same temple"; bible/06-Systems/Legacy-Arc.md section 9.) ONE DIRECTED FRAME,
// the duel's routing - `{t:'wed', data:{to, k, s, why?}}` from a hello'd socket in a PLACE room to the socket `to`
// names, the sender's id AND its verified account stamped on it by the relay (`sub`, off the identity token): each side
// names the OTHER's account to the account service by that stamp (server-account/src/legacy.js realmWed), so who wed
// whom is never a client's own word. The relay reads the shape alone; the law is the two clients' (net/wedSession.js)
// and the account service's:
//   ask   a proposal - the Inspect card's Propose, asked in a temple
//   yes   the asked player's word, sent once their half of the wedding is with the account service
//   no    a proposal declined, taken back, lapsed or refused - with its reason
//   done  the asker's half landed and the union stands; the other reads it from the account service
/** Every kind a wed frame may carry. */
export const WED_KINDS = Object.freeze(['ask', 'yes', 'no', 'done']);
/** Why a proposal came to nothing, as a code the client puts words to (net/wedSession.js wedWhyText). */
export const WED_WHY = Object.freeze(['declined', 'busy', 'temple', 'house', 'wed', 'timeout', 'cancelled', 'refused']);
/** The widest wed frame - an id, a kind, a handshake and a reason. */
export const WED_FRAME_MAX = 512;
/** A socket's wed frames a second: an honest proposal is four frames in a minute. The destination's funnel is its own
 *  per sender (the relay's wed arm), the duel's shape. */
export const WED_HZ_MAX = 2;
export const WED_IN_HZ_MAX = WED_HZ_MAX * 2;
/** The relay that first routes a wed frame (world174, LEGACY7 - world172 on its branch, renumbered past main's WATCH-FIX
 *  and SERPENT3 at the merge) - an older one answers it with 'unknown message' and CLOSES the socket, so no proposal is
 *  sent through it (the Inspect card says the server cannot carry one yet). */
export const WED_RELAY_MIN = 174;
export const relaySupportsWed = (v) => { const m = /^world(\d+)$/.exec(typeof v === 'string' ? v : ''); return !!m && Number(m[1]) >= WED_RELAY_MIN; };
export const wedGate = (bucket, nowMs) => tokenGate(bucket, nowMs, WED_HZ_MAX);
export const wedInGate = (bucket, nowMs) => tokenGate(bucket, nowMs, WED_IN_HZ_MAX);
/**
 * A wed frame's data, projected: `{ to, k, s }` and, on a `no` alone, its `why` - or null (the whole frame refused: a
 * reason on any other kind, an unknown reason, a handshake id outside the duel's alphabet). One home: the relay's
 * parser, the sender's sendWed and the receiver's arm run this same function.
 */
export function validWedData(d) {
  if (!d || typeof d !== 'object' || Array.isArray(d)) return null;
  if (typeof d.k !== 'string' || !WED_KINDS.includes(d.k)) return null;
  const to = typeof d.to === 'string' && ID_RE.test(d.to) ? d.to : null;
  const s = typeof d.s === 'string' && DUEL_SID_RE.test(d.s) ? d.s : null;
  if (!to || !s) return null;
  const out = { to, k: d.k, s };
  if (d.why !== undefined) {
    if (d.k !== 'no' || typeof d.why !== 'string' || !WED_WHY.includes(d.why)) return null;
    out.why = d.why;
  }
  return out;
}

// ═══ WILD1 (2026-10-07, the owner: "Wrothgarian mountains need to be turned into a open pvp zone where ppl when killed
// cant get looted all of the items they have, except campfires, torches, potions etc"; bible/11-Multiplayer/Wild-Zone.md)
// THE OPEN ZONE'S FRAMES. One frame type, `{t:'wild', data}`, from a hello'd socket in a PLACE room (a cell or a world
// room - streamsFoes), in two families:
//
// DIRECTED - `to` names one socket in the room (the relay stamps the sender's id and its verified account `sub`):
//   strike / spell   the duel's blow frames, field for field (validDuelData projects them) - INT9 (bible/06-Systems/
//                    Integrity-Arc.md lane 2): THE RELAY REFEREES THEM (net/wild/wildRef.js) and routes them to nobody; WILD1
//                    had the defender resolve every blow on its own machine, and a defender that never took one never fell
//   worn             the fallen to their killer: the worn pieces their body offers (`s` the death's id) - shown, never
//                    believed: the account service reads the fallen's own record for the piece the killer picks
// INT9's `result` (the defender's answer) and `gave` (the fallen's gift) retired with the defender's word.
//
// ROOM - kept by the relay:
//   zone   my word that I stand in the zone (`z` 1) or have left it (`z` 0) - the referee's fights are between two that
//          both said so (INT9: the relay cannot see the map)
//   pick   the killer's choice of ONE worn piece of a fall of its own (`r` the remains' id, `w` its place in the offer) -
//          the relay waits on it before it signs the fall (net/wild/wildReceipt.js `f1`)
//          (AUDIT INT9: `t`, `m` - the piece's template and material as the offer showed it, signed as the receipt's `wt`)
//   fall   a deposit, WILD_ITEMS_MAX records a frame, `last` on the final one - INT9: every chunk carries the account
//          service's `remains` order (`o` - net/identityToken.js): its id is the order's, its records digest to the
//          order's, or the room keeps none of it (net/wild/wildLaw.js)
//   take   one record off a remains, or `n` of its stack - THE RELAY DECIDES: the first take of a record wins it, and
//          the record itself comes back to its taker alone (`got`); everyone in the room hears what left (`rm`)
// Items are checked for SHAPE only (plain objects, bounded) - the relay cannot import the game's item law; every
// receiver projects each through systems/loot/loot.js validLootList before a field is read (the trade's own law).
// The referee's own word is the `wref` frame (validWildRefOut, below), never a wild frame: the relay routes none a
// client sends.
/** Every kind a wild frame may carry. INT9: `result` and `gave` retired; `zone` its own word. SHIP-PVP (net/sea/seaRef.js):
 *  a captain's word at her helm (`helm`), her shot on another's ship (`shot`), her boarding of her wreck (`board`) - sent
 *  only to a relay that referees them (relaySupportsSeaPvp). */
export const WILD_KINDS = Object.freeze(['strike', 'spell', 'worn', 'pick', 'zone', 'fall', 'take', 'helm', 'shot', 'board']);
/** The kinds that name one socket (`to`); the rest are the room's. INT9: a strike and a spell name their target and are
 *  the referee's, routed to nobody; `worn` alone is routed. SHIP-PVP: a shot names her ship's captain, the referee's too -
 *  sent through the socket of the room that captain stands in; a boarding is the wreck's room's (her captain may be gone). */
export const WILD_DIRECTED = Object.freeze(['strike', 'spell', 'worn', 'shot']);
/** SHIP-PVP: the kinds of the open sea's guns (net/sea/seaRef.js) - each a relay's of world SEA_PVP_RELAY_MIN or newer. */
export const SEA_PVP_KINDS = Object.freeze(['helm', 'shot', 'board']);
/** SHIP-PVP: the first relay that referees the open sea's guns - an older one closes the socket on a kind it does not know. */
export const SEA_PVP_RELAY_MIN = 246;
export const relaySupportsSeaPvp = (v) => { const m = /^world(\d+)$/.exec(typeof v === 'string' ? v : ''); return !!m && Number(m[1]) >= SEA_PVP_RELAY_MIN; };
/** SHIP-PVP: the most hull or canvas one shot word claims (a gathered volley's), and a toughness said in hundredths. */
export const SEA_SHOT_MAX = 8000;
export const SEA_TOUGH_WIRE_MAX = 240;
/** What the room says back: a remains' records (`ri`, a chunk), a record taken (`rm`), a take won (`got`) or lost
 *  (`no`), a remains gone (`gone`); MAC (2026-10-14, the two-phase handoff): a killer's COLLECT (`cr` - the room's signed
 *  word that its killer took the piece the service holds in escrow, net/wild/wildReceipt.js `g1`, for the killer's tab to
 *  carry to the service; an older client drops the kind, so it never takes the room's record of a piece in escrow). */
export const WILD_OUT_KINDS = Object.freeze(['ri', 'rm', 'got', 'no', 'gone', 'cr']);
/** MAC (2026-10-14): the longest collect on the wire (net/wild/wildReceipt.js WILD_RECEIPT_MAX, pinned equal). */
export const WILD_COLLECT_MAX = 512;
/** MAC (2026-10-14): the relay that signs a killer's collect of a piece in escrow - a client asks the service to escrow
 *  its killer's piece only for a room on one (an older room hands the record, and the escrow would hand it twice).
 *  world205, the relay that carries it (201 on its branch: main's world201 is CHAT-TRADE's and world202 FIVE-ASKS',
 *  neither of which signs a collect - left at 201, a tab on either would ask the escrow of a room that hands the record;
 *  203 on the integration, 205 since the merge of main: main's world203 is KG-SET's and world204 KG5's, rooms that hand
 *  the record too). */
export const WILD_COLLECT_RELAY_MIN = 205;
export const relaySupportsWildCollect = (v) => { const m = /^world(\d+)$/.exec(typeof v === 'string' ? v : ''); return !!m && Number(m[1]) >= WILD_COLLECT_RELAY_MIN; };
/** The widest wild frame - a deposit of WILD_ITEMS_MAX heavy records, the trade frame's own bound. */
export const WILD_FRAME_MAX = 12 * 1024;
export const WILD_DATA_MAX = WILD_FRAME_MAX - 96;
/** The most item records one frame carries. */
export const WILD_ITEMS_MAX = 16;
/** The most records one remains holds (a bag and a cart, at most), and how long it lies. */
export const WILD_REMAINS_ITEMS_MAX = 96;
export const WILD_REMAINS_MS = 12 * 60_000;   // PVPDUNGEONS: ten minutes to get back to them AFTER the two minutes' respawn wait (the despawn does not run while the respawn does)
/** The most remains one room keeps - the oldest goes for a new one past it. */
export const WILD_ROOM_REMAINS_MAX = 24;
/** A stack's bound on a take. */
export const WILD_STACK_MAX = 1_000_000;
/** A socket's wild frames a second, out and in - a fight's swings and shafts, a deposit's chunks, a looter's takes. */
export const WILD_HZ_MAX = 12;
export const WILD_IN_HZ_MAX = WILD_HZ_MAX * 2;
/** The relay that first routes a wild frame - an older one CLOSES the socket on a frame type it does not know (the cast
 *  arm's law), so nothing of the zone goes to a relay whose welcome said less. */
export const WILD_RELAY_MIN = 177;   // the zone's one version (renumbered past main's SUPER-DUNGEONS world176)
export const relaySupportsWild = (v) => { const m = /^world(\d+)$/.exec(typeof v === 'string' ? v : ''); return !!m && Number(m[1]) >= WILD_RELAY_MIN; };

// ── PVPDUNGEONS (2026-10-08, the owner: "THOSE HAVE TO WORK!"): THE ZONE'S HALLS, KEPT BY THE HUB ─────────────────────
// The halls themselves are every client's own pure pick (systems/wild/wildDungeons.js) from the DAY - and the day is the
// relay's (`st.day`), never a client's clock, so every player sees the same halls. What no client may decide is kept
