export const SIEGE_END_RESULTS = Object.freeze(['attack', 'defend', 'tie', 'forfeit', 'absent']);
/** The most a roll call names (siegeRef.js SIEGE_FIGHTERS_MAX), the most a field's frame counts in the room. */
