const gateMs = (v) => Number.isSafeInteger(v) && v > 0;
const gateXZ = (v) => finite(v) && Math.abs(v) <= GATE_COURT_BOUND;
const gateHp = (v) => Number.isSafeInteger(v) && v >= 0 && v <= GATE_HP_MAX;
