      if (!Number.isInteger(m.ph) || m.ph < 1 || m.ph > 3 || !gateHp(m.h) || !gateHp(m.m) || m.h > m.m) return null;
      if (!gateXZ(m.x) || !gateXZ(m.z) || !finite(m.yw) || Math.abs(m.yw) > 8 || !Number.isSafeInteger(m.sh) || m.sh < 0 || !gateMs(m.wr)) return null;
