      if (m.d !== undefined && !(Number.isSafeInteger(m.d) && m.d >= 0)) return null;
      const near = typeof m.near === 'string' ? sanitizeName(m.near) : null;
      return { k: 'fell', ...f, ...(m.d !== undefined ? { d: m.d } : {}), ...(near ? { near } : {}) };
